+    fn get_message(
+        &self,
+        id: &nsACString,
+        request: &nsIRequest,
+        listener: &nsIStreamListener,
+    ) -> Result<(), nsresult> {
+        let client = self.try_new_client()?;
+
+        // The client operation is async and we want it to survive the end of
+        // this scope, so spawn it as a detached `moz_task`.
+        moz_task::spawn_local(
+            "get_message",
+            client.get_message(
+                id.to_utf8().into(),
+                RefPtr::new(request),
+                RefPtr::new(listener),
+            ),
+        )
+        .detach();
+
+        Ok(())
+    }
